package com.aistock.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NotificationProxyTest {
 @Test void inboxRoutesAreExact(){String id="00000000-0000-0000-0000-000000000000";assertTrue(ProxyHeaderPolicy.allowed("GET","/api/v1/messages"));assertTrue(ProxyHeaderPolicy.allowed("GET","/api/v1/messages/unread-count"));assertTrue(ProxyHeaderPolicy.allowed("GET","/api/v1/alerts/"+id+"/triggers"));assertTrue(ProxyHeaderPolicy.allowed("PATCH","/api/v1/messages/"+id+"/read"));assertTrue(ProxyHeaderPolicy.allowed("POST","/api/v1/messages/read"));for(String p:new String[]{"/api/v1/messages;evil","/api/v1/messages%2Funread-count","/api/v1/messages/"+id+"/read;evil","/internal/v1/alert-evaluations"})assertFalse(ProxyHeaderPolicy.allowed("GET",p));assertFalse(ProxyHeaderPolicy.allowed("POST","/api/v1/messages"));}
 @Test void forwardsInboxFiltersAndRejectsOwnerAndDuplicateQuery()throws Exception{var c=org.mockito.Mockito.mock(NotificationPublicClient.class);org.mockito.Mockito.when(c.get(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyMap(),org.mockito.ArgumentMatchers.anyMap())).thenReturn(org.springframework.http.ResponseEntity.ok("{}".getBytes()));var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(new NotificationApiProxyController(c,new com.fasterxml.jackson.databind.ObjectMapper())).setControllerAdvice(new com.aistock.common.ApiExceptionHandler()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/messages").param("size","3").param("unreadOnly","true")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());org.mockito.Mockito.verify(c).get(org.mockito.ArgumentMatchers.eq("messages"),org.mockito.ArgumentMatchers.eq(java.util.Map.of("size","3","unreadOnly","true")),org.mockito.ArgumentMatchers.anyMap());for(String query:new String[]{"ownerId=forged","page=1&page=2"})mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/messages?"+query)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());org.mockito.Mockito.verifyNoMoreInteractions(c);}
 @Test void onlyExactAlertRoutesAreAllowed(){assertTrue(ProxyHeaderPolicy.allowed("GET","/api/v1/alerts"));assertTrue(ProxyHeaderPolicy.allowed("POST","/api/v1/alerts"));assertTrue(ProxyHeaderPolicy.allowed("PATCH","/api/v1/alerts/00000000-0000-0000-0000-000000000000"));assertTrue(ProxyHeaderPolicy.allowed("PATCH","/api/v1/notification-preferences"));assertFalse(ProxyHeaderPolicy.allowed("DELETE","/api/v1/alerts/00000000-0000-0000-0000-000000000000"));assertFalse(ProxyHeaderPolicy.allowed("GET","/internal/v1/market/alert-boundary/SH600030"));assertFalse(ProxyHeaderPolicy.allowed("GET","/api/v1/alerts/../internal"));}
 @Test void forwardsOnlySafeHeadersAndQueriesAndBoundsBody()throws Exception{var c=org.mockito.Mockito.mock(NotificationPublicClient.class);org.mockito.Mockito.when(c.get(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyMap(),org.mockito.ArgumentMatchers.anyMap())).thenReturn(org.springframework.http.ResponseEntity.ok("{}".getBytes()));var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(new NotificationApiProxyController(c,new com.fasterxml.jackson.databind.ObjectMapper())).setControllerAdvice(new com.aistock.common.ApiExceptionHandler()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/alerts").param("page","2").param("userId","forged").header("X-User-Id","forged")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk());var q=org.mockito.ArgumentCaptor.forClass(java.util.Map.class);var h=org.mockito.ArgumentCaptor.forClass(java.util.Map.class);org.mockito.Mockito.verify(c).get(org.mockito.ArgumentMatchers.eq("alerts"),q.capture(),h.capture());assertEquals(java.util.Map.of("page","2"),q.getValue());assertFalse(h.getValue().containsKey("X-User-Id"));mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/alerts").content("x".repeat(4097))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isPayloadTooLarge());}
}
